// Package swiftrt is the runtime support library for Go code generated by swift2go.
package swiftrt

import (
	"cmp"
	"fmt"
	"math"
	"reflect"
	"strconv"
	"strings"
)

// Integer is every Go integer type a Swift integer maps to.
type Integer interface {
	~int | ~int8 | ~int16 | ~int32 | ~int64 | ~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64
}

// Unsupported marks a construct swift2go cannot translate yet; reaching it at runtime panics.
func Unsupported[T any](what string) T {
	panic("swift2go: unsupported " + what)
}

// Trap reports a Swift runtime trap.
func Trap(msg string) { panic("swift trap: " + msg) }

func overflow() { Trap("arithmetic overflow") }

func bounds[T Integer]() (min, max int64, unsigned bool, umax uint64) {
	var z T
	switch any(z).(type) {
	case int, int64:
		return math.MinInt64, math.MaxInt64, false, 0
	case int8:
		return math.MinInt8, math.MaxInt8, false, 0
	case int16:
		return math.MinInt16, math.MaxInt16, false, 0
	case int32:
		return math.MinInt32, math.MaxInt32, false, 0
	case uint8:
		return 0, 0, true, math.MaxUint8
	case uint16:
		return 0, 0, true, math.MaxUint16
	case uint32:
		return 0, 0, true, math.MaxUint32
	default:
		return 0, 0, true, math.MaxUint64
	}
}

// Add is Swift's trapping `+`.
func Add[T Integer](a, b T) T {
	r := a + b
	if (r > a) != (b > 0) && b != 0 {
		overflow()
	}
	return r
}

// Sub is Swift's trapping `-`.
func Sub[T Integer](a, b T) T {
	r := a - b
	if (r < a) != (b > 0) && b != 0 {
		overflow()
	}
	return r
}

// Mul is Swift's trapping `*`.
func Mul[T Integer](a, b T) T {
	if a == 0 || b == 0 {
		return 0
	}
	r := a * b
	if r/b != a {
		overflow()
	}
	_, _, unsigned, _ := bounds[T]()
	if !unsigned && (a < 0) != (b < 0) && r > 0 {
		overflow()
	}
	return r
}

// Some wraps a value as a present optional.
func Some[T any](v T) *T { return new(v) }

// Force is Swift's postfix `!` on a value optional.
func Force[T any](p *T) *T {
	if p == nil {
		Trap("unexpectedly found nil while unwrapping an Optional value")
	}
	return p
}

// ForceRef is Swift's postfix `!` on a reference optional.
func ForceRef[T any](v T) T {
	if isNil(v) {
		Trap("unexpectedly found nil while unwrapping an Optional value")
	}
	return v
}

func isNil(v any) bool {
	if v == nil {
		return true
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Pointer, reflect.Map, reflect.Slice, reflect.Func, reflect.Interface:
		return rv.IsNil()
	}
	return false
}

// Coalesce is Swift's `??`.
func Coalesce[T any](p *T, d T) T {
	if p == nil {
		return d
	}
	return *p
}

// Equal is Swift `==` for values Go cannot compare with `==` (slices, maps, optionals).
func Equal[T any](a, b T) bool { return equalValues(reflect.ValueOf(a), reflect.ValueOf(b)) }

var substringType = reflect.TypeFor[Substring]()

// equalValues is reflect.DeepEqual except that Substrings compare by content, as Swift's do.
func equalValues(a, b reflect.Value) bool {
	if !a.IsValid() || !b.IsValid() {
		return a.IsValid() == b.IsValid()
	}
	if a.Type() == substringType && b.Type() == substringType {
		return a.Interface().(Substring).String() == b.Interface().(Substring).String()
	}
	switch a.Kind() {
	case reflect.Slice, reflect.Array:
		if a.Len() != b.Len() {
			return false
		}
		for i := 0; i < a.Len(); i++ {
			if !equalValues(a.Index(i), b.Index(i)) {
				return false
			}
		}
		return true
	case reflect.Pointer:
		if a.IsNil() || b.IsNil() {
			return a.IsNil() && b.IsNil()
		}
		return equalValues(a.Elem(), b.Elem())
	}
	return reflect.DeepEqual(a.Interface(), b.Interface())
}

// Clone copies a slice or map so a Swift `var` binding gets its own value.
func Clone[T any](v T) T {
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Slice:
		if rv.IsNil() {
			return v
		}
		out := reflect.MakeSlice(rv.Type(), rv.Len(), rv.Len())
		reflect.Copy(out, rv)
		return out.Interface().(T)
	case reflect.Map:
		if rv.IsNil() {
			return v
		}
		out := reflect.MakeMapWithSize(rv.Type(), rv.Len())
		for _, k := range rv.MapKeys() {
			out.SetMapIndex(k, rv.MapIndex(k))
		}
		return out.Interface().(T)
	}
	return v
}

// Concat is Swift `+` on arrays.
func Concat[T any](a, b []T) []T {
	out := make([]T, 0, len(a)+len(b))
	return append(append(out, a...), b...)
}

// Describer is a Swift type conforming to CustomStringConvertible.
type Describer interface{ Description() string }

// Str renders a value the way Swift string interpolation does.
func Str(v any) string {
	switch x := v.(type) {
	case nil:
		return "nil"
	case string:
		return x
	case Describer:
		return x.Description()
	case fmt.Stringer:
		return x.String()
	case bool:
		return strconv.FormatBool(x)
	case int:
		return strconv.Itoa(x)
	case float64:
		return formatDouble(x)
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Slice:
		var s strings.Builder
		s.WriteString("[")
		for i := 0; i < rv.Len(); i++ {
			if i > 0 {
				s.WriteString(", ")
			}
			s.WriteString(debugStr(rv.Index(i).Interface()))
		}
		return s.String() + "]"
	case reflect.Pointer:
		if rv.IsNil() {
			return "nil"
		}
		return "Optional(" + debugStr(rv.Elem().Interface()) + ")"
	}
	return fmt.Sprint(v)
}

func debugStr(v any) string {
	if s, ok := v.(string); ok {
		return strconv.Quote(s)
	}
	return Str(v)
}

func formatDouble(f float64) string { return swiftFloatDescription(f, 64) }

// Is is Swift's `is`.
func Is[T any](v any) bool {
	if _, ok := v.(T); ok {
		return true
	}
	if _, ok := derefAs[T](v); ok {
		return true
	}
	if _, ok := Dynamic(v).(T); ok {
		return true
	}
	_, ok := bridgeAs[T](v)
	return ok
}

// As is Swift's `as?`.
func As[T any](v any) *T {
	if t, ok := v.(T); ok {
		return &t
	}
	if t, ok := Dynamic(v).(T); ok {
		return &t
	}
	if t, ok := derefAs[T](v); ok {
		return &t
	}
	if t, ok := bridgeAs[T](v); ok {
		return &t
	}
	return nil
}

// MustAs is Swift's `as!`.
func MustAs[T any](v any) T {
	t, ok := v.(T)
	if !ok {
		t, ok = Dynamic(v).(T)
	}
	if !ok {
		t, ok = derefAs[T](v)
	}
	if !ok {
		t, ok = bridgeAs[T](v)
	}
	if !ok {
		Trap(fmt.Sprintf("could not cast value of type %T", v))
	}
	return t
}

// Max is Swift's max(_:_:).
func Max[T cmp.Ordered](a, b T) T {
	if b >= a {
		return b
	}
	return a
}

// Min is Swift's min(_:_:).
func Min[T cmp.Ordered](a, b T) T {
	if b < a {
		return b
	}
	return a
}

// Same is Swift `===`: identity of two class references, either of which may be nil.
func Same(a, b any) bool {
	if isNil(a) || isNil(b) {
		return isNil(a) && isNil(b)
	}
	return Dynamic(a) == Dynamic(b)
}

// Dynamic returns the most-derived object behind a class reference that may be an embedded superclass.
func Dynamic(v any) any {
	if d, ok := v.(interface{ SwiftDynamic() any }); ok && !isNil(v) {
		return d.SwiftDynamic()
	}
	return v
}

// Ref boxes a struct value for an existential whose methods need a pointer receiver.
func Ref[T any](v T) *T { return new(v) }

// derefAs matches v against T when v is a boxed *T.
func derefAs[T any](v any) (T, bool) {
	if p, ok := v.(*T); ok && p != nil {
		return *p, true
	}
	var zero T
	return zero, false
}

// CoalesceRef is Swift `??` on a class reference, which Go represents as a nil-able pointer.
func CoalesceRef[T any](p, d T) T {
	if isNil(p) {
		return d
	}
	return p
}

// CoalesceOpt is Swift `??` whose right side is itself optional.
func CoalesceOpt[T any](p, q T) T {
	if isNil(p) {
		return q
	}
	return p
}

// Flat collapses a runtime optional of a class reference (**C) to the emitter's nil-able *C.
func Flat[T any](p *T) T {
	if p == nil {
		var zero T
		return zero
	}
	return *p
}

// UnitFn0 adapts a Void closure to a generic body that returns a value.
func UnitFn0(f func()) func() struct{} { return func() struct{} { f(); return struct{}{} } }

// UnitFn1 adapts a one-argument Void closure to a generic body that returns a value.
func UnitFn1[A any](f func(A)) func(A) struct{} {
	return func(a A) struct{} { f(a); return struct{}{} }
}

// AnyFn0 adapts a Void closure to a parameter whose generic result became `any`.
func AnyFn0(f func()) func() any { return func() any { f(); return nil } }

// AnyFn1 adapts a one-argument Void closure to a parameter whose generic result became `any`.
func AnyFn1[A any](f func(A)) func(A) any { return func(a A) any { f(a); return nil } }

// AnyFn2 adapts a two-argument Void closure to a parameter whose generic result became `any`.
func AnyFn2[A, B any](f func(A, B)) func(A, B) any { return func(a A, b B) any { f(a, b); return nil } }
